package main
import("bufio";"encoding/json";"flag";"fmt";"os";"os/exec";"strings")
type Row struct{Time string `json:"time_usec"`;Unit string `json:"unit"`;Priority string `json:"priority"`;Message string `json:"message"`}
func parse(text string)([]Row,error){out:=[]Row{};scan:=bufio.NewScanner(strings.NewReader(text));scan.Buffer(make([]byte,4096),2<<20);for scan.Scan(){var raw map[string]json.RawMessage;if e:=json.Unmarshal(scan.Bytes(),&raw);e!=nil{return nil,e};get:=func(k string)string{var s string;if json.Unmarshal(raw[k],&s)==nil{return s};return string(raw[k])};out=append(out,Row{get("__REALTIME_TIMESTAMP"),get("_SYSTEMD_UNIT"),get("PRIORITY"),get("MESSAGE")})};return out,scan.Err()}
func main(){unit:=flag.String("unit","","systemd unit filter");since:=flag.String("since","today","journalctl since expression");limit:=flag.Int("limit",100,"maximum records 1..500");flag.Parse();if *limit<1||*limit>500||flag.NArg()!=0{fmt.Fprintln(os.Stderr,"invalid limit/arguments");os.Exit(2)};args:=[]string{"--no-pager","-o","json","-n",fmt.Sprint(*limit),"--since",*since};if *unit!=""{args=append(args,"--unit",*unit)};b,e:=exec.Command("journalctl",args...).Output();if e!=nil{fmt.Fprintln(os.Stderr,"journalctl unavailable or permission/query failure:",e);os.Exit(1)};rows,e:=parse(string(b));if e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)};encoder:=json.NewEncoder(os.Stdout);encoder.SetIndent("","  ");if e=encoder.Encode(rows);e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)}}
